// Command gencore reads the core.API interface and writes the shell's
// forwarder, the JSON-RPC client and the JSON-RPC dispatcher. A method is
// written once, in the interface. The forwarder checks every parameter whose
// type has a Validate() error method before routing the call.
package main

import (
	"fmt"
	"go/types"
	"path"
	"strings"

	"golang.org/x/tools/go/packages"
	"golang.org/x/tools/imports"
)

// outputs are the generated files: path from the repo root, and the
// function that writes it.
var outputs = []struct {
	path string
	emit func(api *types.Package, methods []method) *file
}{
	{"internal/app/forwarder_gen.go", emitForwarder},
	{"internal/remote/client_gen.go", emitClient},
	{"internal/remote/dispatch_gen.go", emitDispatch},
}

const header = "// Code generated by gencore; DO NOT EDIT.\n\n"

// route is the Router method that picks a method's core. translates is set
// when that Router method also takes the call's context and returns the
// argument in the form its core knows, passed on in place of the caller's.
type route struct {
	method     string
	translates bool
}

// routes maps the type of a method's second parameter to its route. Any
// other type means the local core.
var routes = map[string]route{
	"github.com/brogli/gaertli/internal/core.WorktreeID": {method: "CoreOf", translates: true},
	"github.com/brogli/gaertli/internal/core.RepoPath":   {method: "CoreFor"},
}

// coreArg names the translated argument in a generated Forwarder method.
const coreArg = "coreID"

type param struct {
	name      string
	typ       types.Type
	validated bool // the value, or each element of the slice, has Validate() error
}

type method struct {
	name   string
	params []param // without ctx
	result types.Type
	router route // zero for the local core
}

// Generate loads the package in dir, validates its API interface and returns
// the generated files keyed by their paths in outputs.
func Generate(dir string) (map[string][]byte, error) {
	pkg, err := load(dir)
	if err != nil {
		return nil, err
	}
	methods, err := readAPI(pkg)
	if err != nil {
		return nil, err
	}
	files := map[string][]byte{}
	for _, out := range outputs {
		src, err := out.emit(pkg, methods).source()
		if err != nil {
			return nil, fmt.Errorf("%s: %w", out.path, err)
		}
		files[out.path] = src
	}
	return files, nil
}

func load(dir string) (*types.Package, error) {
	cfg := &packages.Config{Mode: packages.NeedName | packages.NeedTypes, Dir: dir}
	pkgs, err := packages.Load(cfg, ".")
	if err != nil {
		return nil, err
	}
	if packages.PrintErrors(pkgs) > 0 {
		return nil, fmt.Errorf("package %s has errors", dir)
	}
	return pkgs[0].Types, nil
}

func readAPI(pkg *types.Package) ([]method, error) {
	obj := pkg.Scope().Lookup("API")
	if obj == nil {
		return nil, fmt.Errorf("%s: no type API", pkg.Path())
	}
	iface, ok := obj.Type().Underlying().(*types.Interface)
	if !ok {
		return nil, fmt.Errorf("%s: API is not an interface", pkg.Path())
	}
	var methods []method
	for method := range iface.Methods() {
		m, err := readMethod(method)
		if err != nil {
			return nil, err
		}
		methods = append(methods, m)
	}
	return methods, nil
}

func readMethod(fn *types.Func) (method, error) {
	sig := fn.Signature()
	m := method{name: fn.Name()}
	fail := func(format string, args ...any) (method, error) {
		return method{}, fmt.Errorf(m.name+": "+format, args...)
	}

	params := sig.Params()
	if params.Len() == 0 || types.TypeString(params.At(0).Type(), nil) != "context.Context" {
		return fail("first parameter must be context.Context")
	}
	for i := 1; i < params.Len(); i++ {
		p := params.At(i)
		if p.Name() == "" || p.Name() == "_" {
			return fail("parameter %d has no name", i+1)
		}
		if bad := nonJSON(p.Type()); bad != nil {
			return fail("parameter %s: %s is not JSON-serialisable", p.Name(), bad)
		}
		m.params = append(m.params, param{p.Name(), p.Type(), validated(p.Type())})
	}
	if len(m.params) > 0 {
		m.router = routes[types.TypeString(m.params[0].typ, nil)]
	}

	results := sig.Results()
	if n := results.Len(); n == 0 || n > 2 || !types.Identical(results.At(n-1).Type(), types.Universe.Lookup("error").Type()) {
		return fail("last result must be error")
	}
	if results.Len() == 2 {
		if bad := nonJSON(results.At(0).Type()); bad != nil {
			return fail("result: %s is not JSON-serialisable", bad)
		}
		m.result = results.At(0).Type()
	}
	return m, nil
}

// nonJSON returns the first type inside t that encoding/json cannot carry.
func nonJSON(t types.Type) types.Type {
	seen := map[types.Type]bool{}
	var walk func(types.Type) types.Type
	walk = func(t types.Type) types.Type {
		if seen[t] {
			return nil
		}
		seen[t] = true
		switch u := t.Underlying().(type) {
		case *types.Basic:
			return nil
		case *types.Chan, *types.Signature:
			return t
		case *types.Interface:
			if u.NumMethods() > 0 {
				return t
			}
			return nil
		case *types.Pointer:
			return walk(u.Elem())
		case *types.Slice:
			return walk(u.Elem())
		case *types.Array:
			return walk(u.Elem())
		case *types.Map:
			if k, ok := u.Key().Underlying().(*types.Basic); !ok || k.Info()&(types.IsString|types.IsInteger) == 0 {
				return u.Key()
			}
			return walk(u.Elem())
		case *types.Struct:
			for field := range u.Fields() {
				if bad := walk(field.Type()); bad != nil {
					return bad
				}
			}
			return nil
		}
		return t
	}
	return walk(t)
}

// validated reports whether t, or t's element if t is a slice, has a
// Validate() error method.
func validated(t types.Type) bool {
	if s, ok := t.Underlying().(*types.Slice); ok {
		t = s.Elem()
	}
	sel := types.NewMethodSet(t).Lookup(nil, "Validate")
	if sel == nil {
		return false
	}
	sig := sel.Obj().(*types.Func).Signature()
	return sig.Params().Len() == 0 && sig.Results().Len() == 1 &&
		types.Identical(sig.Results().At(0).Type(), types.Universe.Lookup("error").Type())
}

// file collects generated code and the imports its type names need.
type file struct {
	pkg     string
	imports map[string]string // path → name
	body    strings.Builder
}

// newFile starts a file in package pkg that imports api and stdImports.
func newFile(pkg string, api *types.Package, stdImports ...string) *file {
	f := &file{pkg: pkg, imports: map[string]string{api.Path(): api.Name()}}
	for _, p := range stdImports {
		f.imports[p] = path.Base(p)
	}
	return f
}

func (f *file) typ(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		f.imports[p.Path()] = p.Name()
		return p.Name()
	})
}

func (f *file) printf(format string, args ...any) {
	fmt.Fprintf(&f.body, format, args...)
}

// source renders the file; goimports groups and sorts the imports.
func (f *file) source() ([]byte, error) {
	var b strings.Builder
	b.WriteString(header)
	fmt.Fprintf(&b, "package %s\n\nimport (\n", f.pkg)
	for p := range f.imports {
		fmt.Fprintf(&b, "\t%q\n", p)
	}
	b.WriteString(")\n\n")
	b.WriteString(f.body.String())
	return imports.Process("", []byte(b.String()), &imports.Options{Comments: true, TabIndent: true, TabWidth: 8, FormatOnly: true})
}

// signature renders "ctx context.Context, wt core.WorktreeID" and lists the
// args.
func (f *file) signature(m method) (params string, args []string) {
	ps := []string{"ctx context.Context"}
	args = []string{"ctx"}
	for _, p := range m.params {
		ps = append(ps, p.name+" "+f.typ(p.typ))
		args = append(args, p.name)
	}
	return strings.Join(ps, ", "), args
}

func (f *file) results(m method) string {
	if m.result == nil {
		return "error"
	}
	return "(" + f.typ(m.result) + ", error)"
}

// returnErr returns err from a method with m's results.
func (f *file) returnErr(m method) {
	if m.result == nil {
		f.printf("\t\treturn err\n")
	} else {
		f.printf("\t\tvar zero %s\n\t\treturn zero, err\n", f.typ(m.result))
	}
}

// emitForwarder writes the Forwarder: each method checks its validated
// parameters, then forwards the call to the core the Router names.
func emitForwarder(pkg *types.Package, methods []method) *file {
	f := newFile("app", pkg, "context")
	for _, m := range methods {
		params, args := f.signature(m)
		f.printf("func (f *Forwarder) %s(%s) %s {\n", m.name, params, f.results(m))
		for _, p := range m.params {
			if !p.validated {
				continue
			}
			spread := ""
			if _, ok := p.typ.Underlying().(*types.Slice); ok {
				spread = "..."
			}
			f.printf("\tif err := validateEach(%s%s); err != nil {\n", p.name, spread)
			f.returnErr(m)
			f.printf("\t}\n")
		}
		if m.router.method == "" {
			f.printf("\treturn f.router.Local().%s(%s)\n", m.name, strings.Join(args, ", "))
		} else {
			routed, routeArgs := "c", m.params[0].name
			if m.router.translates {
				routed += ", " + coreArg
				routeArgs = "ctx, " + routeArgs
				args[1] = coreArg
			}
			f.printf("\t%s, err := f.router.%s(%s)\n\tif err != nil {\n", routed, m.router.method, routeArgs)
			f.returnErr(m)
			f.printf("\t}\n\treturn c.%s(%s)\n", m.name, strings.Join(args, ", "))
		}
		f.printf("}\n\n")
	}
	return f
}

func paramsType(m method) string {
	return strings.ToLower(m.name[:1]) + m.name[1:] + "Params"
}

func fieldName(p param) string {
	return strings.ToUpper(p.name[:1]) + p.name[1:]
}

func emitClient(pkg *types.Package, methods []method) *file {
	f := newFile("remote", pkg, "context")
	f.printf("var _ %s.API = (*Client)(nil)\n\n", pkg.Name())
	for _, m := range methods {
		params, _ := f.signature(m)
		if len(m.params) > 0 {
			f.printf("type %s struct {\n", paramsType(m))
			for _, p := range m.params {
				f.printf("\t%s %s `json:%q`\n", fieldName(p), f.typ(p.typ), p.name)
			}
			f.printf("}\n\n")
		}
		f.printf("func (c *Client) %s(%s) %s {\n", m.name, params, f.results(m))
		lit := "nil"
		if len(m.params) > 0 {
			var fields []string
			for _, p := range m.params {
				fields = append(fields, fieldName(p)+": "+p.name)
			}
			lit = paramsType(m) + "{" + strings.Join(fields, ", ") + "}"
		}
		if m.result == nil {
			f.printf("\treturn c.call(ctx, %q, %s, nil)\n", m.name, lit)
		} else {
			f.printf("\tvar result %s\n\terr := c.call(ctx, %q, %s, &result)\n\treturn result, err\n", f.typ(m.result), m.name, lit)
		}
		f.printf("}\n\n")
	}
	return f
}

func emitDispatch(pkg *types.Package, methods []method) *file {
	f := newFile("remote", pkg, "context", "github.com/creachadair/jrpc2/handler")
	f.printf("func handlers(api %s.API) handler.Map {\n\treturn handler.Map{\n", pkg.Name())
	for _, m := range methods {
		in := "ctx context.Context"
		args := []string{"ctx"}
		if len(m.params) > 0 {
			in += ", p " + paramsType(m)
			for _, p := range m.params {
				args = append(args, "p."+fieldName(p))
			}
		}
		f.printf("\t\t%q: handler.New(func(%s) %s {\n\t\t\treturn api.%s(%s)\n\t\t}),\n",
			m.name, in, f.results(m), m.name, strings.Join(args, ", "))
	}
	f.printf("\t}\n}\n")
	return f
}
